1	// Loads the built site in headless Chromium and exits non-zero if a page renders blank.
2	// Usage: node web/check-render.mjs [baseUrl] [runId] [screenshotDir]
3	// Needs the API (which also serves web/dist) already running and `chromium` on PATH.
4	import { spawnSync } from "node:child_process";
5	import { mkdirSync } from "node:fs";
6	import { tmpdir } from "node:os";
7	import { join } from "node:path";
8	
9	const base = process.argv[2] ?? "http://REDACTED:8787";
10	const runId = process.argv[3] ?? "20261010T101804Z-5c3370f";
11	const outDir = process.argv[4] ?? join(tmpdir(), "resurgo-shots");
12	mkdirSync(outDir, { recursive: true });
13	
14	const pages = [["landing", "/"], ["runs", "/runs"], ["run", `/runs/${runId}`]];
15	// Blink's preferredColorScheme enum: 0 is dark, 1 is light.
16	const themes = [["dark", 0], ["light", 1]];
17	
18	const chromium = (args) =>
19	  spawnSync("chromium", ["--headless=new", "--disable-gpu", "--no-sandbox", "--virtual-time-budget=6000", ...args], {
20	    encoding: "utf8",
21	    maxBuffer: 64 * 1024 * 1024,
22	  });
23	
24	/** Text inside #root: everything after its opening tag, minus scripts and markup. */
25	function rootText(dom) {
26	  const at = dom.search(/<div id="root"[^>]*>/);
27	  if (at < 0) return "";
28	  return dom
29	    .slice(at)
30	    .replace(/<(script|style)[\s\S]*?<\/\1>/g, "")
31	    .replace(/<[^>]+>/g, " ")
32	    .replace(/\s+/g, " ")
33	    .trim();
34	}
35	
36	let failed = false;
37	for (const [name, path] of pages) {
38	  const url = base + path;
39	  const r = chromium(["--dump-dom", url]);
40	  const dom = r.stdout ?? "";
41	  const text = rootText(dom);
42	  const broken = /could not be shown/.test(text);
43	  const ok = r.status === 0 && text.length >= 80 && !broken;
44	  failed ||= !ok;
45	  console.log(`${ok ? "PASS" : "FAIL"} ${path}  root text: ${text.length} chars${broken ? ", a section failed to render" : ""}`);
46	  if (!ok && r.stderr) console.log(r.stderr.split("\n").slice(-5).join("\n"));
47	  for (const [theme, scheme] of themes) {
48	    const shot = join(outDir, `${name}-${theme}.png`);
49	    chromium([`--blink-settings=preferredColorScheme=${scheme}`, "--window-size=1280,1800", `--screenshot=${shot}`, url]);
50	    console.log(`  screenshot ${shot}`);
51	  }
52	}
53	process.exit(failed ? 1 : 0);
54

