// Scratch: measure horizontal overflow and inner h-scrollbars via CDP, and take screenshots.
// node measure.mjs <base> <outDir> <path>... ; env WIDTHS="420,1280"
import { spawn } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const [base, outDir, ...paths] = process.argv.slice(2);
const widths = (process.env.WIDTHS ?? "420,1280").split(",").map(Number);
mkdirSync(outDir, { recursive: true });
const port = 9333 + Math.floor(Math.random() * 500);
const proc = spawn("chromium", ["--headless=new", "--disable-gpu", "--no-sandbox", `--remote-debugging-port=${port}`, "--user-data-dir=" + join(outDir, ".profile"), "about:blank"], { stdio: "ignore" });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let list;
for (let i = 0; i < 50; i++) {
  try { list = await (await fetch(`http://REDACTED:${port}/json`)).json(); if (list.length) break; } catch {}
  await sleep(200);
}
const ws = new WebSocket(list.find((t) => t.type === "page").webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let id = 0; const pending = new Map();
ws.onmessage = (m) => { const d = JSON.parse(m.data); if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); } };
const send = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const evalJs = async (expr) => (await send("Runtime.evaluate", { expression: expr, returnByValue: true, awaitPromise: true })).result.result.value;

const probe = `(() => {
  const vw = document.documentElement.clientWidth;
  const sel = (e) => e.tagName.toLowerCase() + (e.id ? '#' + e.id : '') + '.' + String(e.className && e.className.baseVal === undefined ? e.className : '').split(/\\s+/).slice(0, 6).join('.');
  const over = [];
  for (const e of document.querySelectorAll('body *')) {
    const r = e.getBoundingClientRect();
    if (r.width && r.right > vw + 1) {
      // keep only elements whose parent does not itself extend further (the source)
      over.push({ el: sel(e), right: Math.round(r.right), width: Math.round(r.width), text: (e.textContent || '').trim().slice(0, 40) });
    }
  }
  const inner = [];
  for (const e of document.querySelectorAll('body *')) {
    const cs = getComputedStyle(e);
    if ((cs.overflowX === 'auto' || cs.overflowX === 'scroll') && e.scrollWidth > e.clientWidth + 1)
      inner.push({ el: sel(e), scrollWidth: e.scrollWidth, clientWidth: e.clientWidth });
  }
  return JSON.stringify({ vw, docScrollWidth: document.documentElement.scrollWidth, bodyScrollWidth: document.body.scrollWidth, over: over.slice(0, 12), inner });
})()`;

const out = [];
for (const path of paths) {
  for (const w of widths) {
    for (const scheme of ["light", "dark"]) {
      await send("Emulation.setDeviceMetricsOverride", { width: w, height: 900, deviceScaleFactor: 1, mobile: false });
      await send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-color-scheme", value: scheme }] });
      await send("Page.navigate", { url: base + path });
      await sleep(5500);
      // Run view: expand any step with collapsed output so long lines are present.
      const m = JSON.parse(await evalJs(probe));
      const name = `${path === "/" ? "landing" : path.replace(/^\//, "").replace(/[^a-z0-9]+/gi, "-").slice(0, 14)}-${w}-${scheme}.png`;
      const h = await evalJs("document.documentElement.scrollHeight");
      await send("Emulation.setDeviceMetricsOverride", { width: w, height: Math.min(h, 6000), deviceScaleFactor: 1, mobile: false });
      const shot = await send("Page.captureScreenshot", { format: "png" });
      writeFileSync(join(outDir, name), Buffer.from(shot.result.data, "base64"));
      out.push({ path, w, scheme, shot: join(outDir, name), ...m });
    }
  }
}
console.log(JSON.stringify(out, null, 1));
ws.close(); proc.kill();
process.exit(0);

