                  <span className="tabular-nums text-muted-foreground">{fmtDur(v.duration_s)}</span>
                </p>
                <p className="mt-2 truncate font-mono text-xs text-muted-foreground" title={v.command}>$ {v.command}</p>
              </li>
            ))}
          </ul>
        </>
      )}

